\documentclass[11pt]{article}
\usepackage[T1]{fontenc}
\usepackage[margin=1in]{geometry}
\setlength{\parindent}{0pt}
\setlength{\parskip}{0.65em}
\begin{document}
\pagestyle{empty}
First paragraph: flush left, no indentation.

Second paragraph: flush left, with the configured gap above it.

{\setlength{\parindent}{2em}\setlength{\parskip}{1.3em}
Third paragraph: local indentation and double paragraph gap.\par
Fourth paragraph: the local register values still apply.\par}

Fifth paragraph: original zero indentation and smaller gap restored.
\section*{A heading between paragraphs}
Sixth paragraph: heading spacing and paragraph spacing must both be applied.

Seventh paragraph: baseline paragraph spacing resumes.
\end{document}
